WITH metrics AS (SELECT *, LEAD(quantity) OVER w_grp AS next_quantity, LAG(quantity) OVER w_grp AS prev_quantity, ROW_NUMBER() OVER w_grp AS row_seq, AVG(quantity) OVER (PARTITION BY store_id ORDER BY quantity, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS quantity_avg_6_prior FROM inventory WINDOW w_grp AS (PARTITION BY product_id, store_id ORDER BY quantity, id)) SELECT CASE WHEN quantity >= 269 THEN 'PREMIUM' ELSE 'STANDARD' END AS quantity_tier, ROUND(AVG(next_quantity), 2) AS avg_next_quantity, APPROX_PERCENTILE(quantity_avg_6_prior, 0.95) AS quantity_avg_6_prior_p95, COUNT(*) AS row_count, COUNT(*) AS event_count, MIN(prev_quantity) AS min_prev_quantity FROM metrics GROUP BY CASE WHEN quantity >= 269 THEN 'PREMIUM' ELSE 'STANDARD' END HAVING MIN(prev_quantity) >= 0;
